1	import React from 'react';
2	import { Box, Checkbox, Flex, Text } from '@chakra-ui/react';
3	import { useIntl } from 'react-intl';
4	import { ADD_FILTER, REMOVE_FILTER } from 'app/utils/refinementValues';
5	
6	export type ZimmCheckboxProps = {
7	  value: string;
8	  label: string;
9	  isChecked: boolean;
10	  onChange: (value: string, isCurrentlySelected: boolean) => void;
11	  /** When 0 and not selected the option is hidden — pass undefined to always show. */
12	  hitCount?: number;
13	  /** Renders a filled colour dot beside the label when set (e.g. a CSS colour string). */
14	  swatchColour?: string;
15	};
16	
17	/**
18	 * Single branded checkbox row with optional colour swatch. Handles its own
19	 * hit-count visibility guard and aria-label state (Add / Remove filter).
20	 *
21	 * For lists of options, compose via `ZimmCheckboxGroup`.
22	 */
23	export const ZimmCheckbox = ({ value, label, isChecked, onChange, hitCount, swatchColour }: ZimmCheckboxProps) => {
24	  const intl = useIntl();
25	
26	  if (hitCount === 0 && !isChecked) return null;
27	
28	  return (
29	    <Checkbox
30	      isChecked={isChecked}
31	      onChange={() => onChange(value, isChecked)}
32	      aria-label={intl.formatMessage(isChecked ? REMOVE_FILTER : ADD_FILTER, { label })}
33	      spacing="var(--zimm-scale-s)"
34	      sx={{
35	        '.chakra-checkbox__control': {
36	          borderColor: 'var(--zimm-color-border-default)',
37	          _checked: {
38	            background: 'var(--zimm-color-action-primary-bg-default)',
39	            borderColor: 'var(--zimm-color-action-primary-bg-default)',
40	            color: 'var(--zimm-color-action-primary-text)',
41	          },
42	          // Brand focus ring — dropping the indicator fails WCAG 2.2 AA SC 2.4.7.
43	          _focusVisible: {
44	            outline: 'var(--zimm-focus-ring)',
45	            outlineOffset: 0,
46	            boxShadow: 'none',
47	          },
48	        },
49	      }}
50	    >
51	      <Flex align="center" gap="var(--zimm-scale-s)">
52	        {swatchColour !== undefined && (
53	          <Box
54	            data-testid="zimm-colour-swatch"
55	            boxSize="var(--zimm-icon-size-md)"
56	            borderRadius="full"
57	            border="var(--zimm-border-width-default) solid var(--zimm-color-border-default)"
58	            flexShrink={0}
59	            background={swatchColour || 'transparent'}
60	          />
61	        )}
62	        <Text as="span" textStyle="navigation">
63	          {label}
64	        </Text>
65	      </Flex>
66	    </Checkbox>
67	  );
68	};
