1	import React from 'react';
2	import { Stack } from '@chakra-ui/react';
3	import { ZimmCheckbox } from 'app/components/ui-kits/atoms/zimmCheckbox';
4	
5	export type ZimmCheckboxGroupOption = {
6	  value: string;
7	  label: string;
8	  /** When 0 and not selected the option is hidden — pass undefined to always show. */
9	  hitCount?: number;
10	  /** Renders a filled colour dot beside the label when set (e.g. a CSS colour string). */
11	  swatchColour?: string;
12	};
13	
14	type ZimmCheckboxGroupProps = {
15	  options: readonly ZimmCheckboxGroupOption[];
16	  selectedValues: readonly string[];
17	  /** Called with the option value and whether it was already selected (true = deselect). */
18	  onChange: (value: string, isCurrentlySelected: boolean) => void;
19	};
20	
21	/**
22	 * Generic checkbox list for multi-select filtering. Not tied to SFCC or any specific data
23	 * shape — accepts plain option objects so it can be used in filter drawers, preference forms,
24	 * or any multi-select surface.
25	 *
26	 * Each row is a `ZimmCheckbox` atom; hit-count visibility and swatch rendering are
27	 * delegated there.
28	 */
29	export const ZimmCheckboxGroup = ({ options, selectedValues, onChange }: ZimmCheckboxGroupProps) => (
30	  <Stack spacing="var(--zimm-scale-m)">
31	    {options.map((option) => (
32	      <ZimmCheckbox
33	        key={option.value}
34	        value={option.value}
35	        label={option.label}
36	        hitCount={option.hitCount}
37	        swatchColour={option.swatchColour}
38	        isChecked={selectedValues.includes(option.value)}
39	        onChange={onChange}
40	      />
41	    ))}
42	  </Stack>
43	);
