120	/**
121	 * SFCC image-sizing follow-up — this grid's own real per-breakpoint tile width, as a fraction of
122	 * viewport width, forwarded to `ZimmProductCard`'s `imageWidths` (→ `ZimmProductCardMedia` →
123	 * `DynamicImage`). Derived directly from this file's own `SimpleGrid columns={[2, 2, 4, 5]}`
124	 * below (2 cols base/sm, 4 at `md`, 5 at `lg` and up — matching `theme/foundation/gridSystem.ts`'s
125	 * breakpoints, which this app's registered theme uses verbatim) — approximated as `(100 /
126	 * columns)vw` per step, ignoring the grid's own container padding/column-gap for simplicity
127	 * (standard practice for a `sizes`/`widths` ladder: DynamicImage always requests the next size up
128	 * in its own generated `srcSet`, so a close-enough fraction is sufficient, never an under-fetch).
129	 * Update this alongside the SimpleGrid's own `columns` prop if that ever changes — the two are
130	 * not otherwise linked.
131	 */
132	const PLP_IMAGE_WIDTHS: ZimmMediaTileWidths = { base: '50vw', md: '25vw', lg: '20vw' };
133	
134	/**
135	 * SFCC image-sizing follow-up — PLP images resize via DIS `sw=` only; quality (`&q=`) is
136	 * deliberately omitted so the resize doesn't also change the source-encoded quality shoppers
137	 * already see today. See `buildDisImageSrc`'s own JSDoc for why this differs from the PDP
138	 * gallery's own explicit quality default (90).
139	 */
140	const PLP_IMAGE_QUALITY = null;
141	
142	/**
143	 * SFCC image-sizing/LCP follow-up (2026-09-20) — how many of the FIRST rendered tiles skip
144	 * lazy-loading (`priority` → `ZimmProductCardMedia`'s `loading: 'eager'` → base SFCC's own
145	 * `getImageAttributes` auto-`fetchpriority: 'high'` → a real SSR `<link rel="preload">`).
146	 *
147	 * Deliberately a fixed `2`, not "the whole first row" (up to 5 on desktop's `SimpleGrid
148	 * columns={[2, 2, 4, 5]}` above) — there is no server-side viewport/device signal anywhere in
149	 * this codebase (`overrides/app/components/responsive/index.tsx`'s `HideOnMobile`/`HideOnDesktop`
150	 * are pure CSS `display` toggles, not real detection), so the SAME HTML — and therefore the same
151	 * `priority` markers — ships to every device regardless of its real column count. Sizing this for
152	 * desktop's full first row (5) would make a mobile visitor eagerly fetch 3 images they can't even
153	 * see yet, directly working against AGENTS.md's mobile-specific LCP budget (`≤2s p75 mobile`) and
154	 * the client's own sub-1s target — a strictly worse trade than the accepted gap here (desktop's
155	 * rows 2-3 stay lazy despite being visible without scrolling; native lazy-load's own near-viewport
156	 * threshold should still pick them up almost immediately in practice). `2` matches the smallest
157	 * real column count (`base`/`sm`), so it is never wrong for the metric that matters most, only
158	 * conservative for wider ones.
159	 */
160	const PLP_PRIORITY_TILE_COUNT = 2;
161	
162	// Same attributeId OOTB's own Refinements.jsx componentMap keys ColorRefinements on —
163	// used here to gate the colour swatch dot to the colour facet only.
164	const COLOR_REFINEMENT_ATTRIBUTE_ID = 'c_refinementColor';
165	// Same attributeId OOTB's own Refinements.jsx componentMap keys SizeRefinements on — used
166	// here to route the Size facet to ZimmSizeFilter (button/chip grid) instead of
167	// ZimmCheckboxGroup (checkbox design).
168	const SIZE_REFINEMENT_ATTRIBUTE_ID = 'c_size';
169	
170	
171	// SFCC-83/84 quick test integration — this page's own toast constants (imported above) are all
172	// wishlist-specific; add-to-bag needed its own message rather than reusing one of those under a
173	// misleading label.
174	const messages = defineMessages({
175	  addedToBag: { id: 'product_list.toast.added_to_bag', defaultMessage: 'Added to bag' },
176	  recentlyViewedTitle: {
177	    id: 'product_list.recommended_products.title.recently_viewed',
178	    defaultMessage: 'Recently Viewed',
179	  },
180	});
