182	/**
183	 * Props as declared by the base template's own (removed) PropTypes, plus `staticContext` — the
184	 * react-router route-component prop this page receives when rendered via `<Route
185	 * component={ProductList} />` (v5.3.4, a plain JS package with no bundled or @types definitions
186	 * in this repo, so `unknown` is the honest ceiling here — same reasoning as `category` below).
187	 * Everything else lands in `...rest` and is spread onto the root `<Box>` exactly as it did in
188	 * the untyped base file; this type only makes the existing shape explicit, it does not change
189	 * what is accepted at runtime.
190	 */
191	type ProductListProps = {
192	  onAddToWishlistClick?: () => void;
193	  onRemoveWishlistClick?: () => void;
194	  /** Set by the categoryPath dispatcher, which resolves `/clothing/dresses` to its category id. */
195	  categoryId?: string;
196	  category?: unknown;
197	  isLoading?: boolean;
198	  staticContext?: unknown;
199	} & Record<string, unknown>;
200	
201	/**
202	 * Quick test integration only (SFCC-83/84) — swaps the base `ProductTile` for the shared
203	 * `ZimmProductCard` (`variation: 'plp'`) so it can be exercised against a real PLP grid. Not the
204	 * final PLP implementation: it still needs the "product card group" component this grid doesn't
205	 * have yet. Owns its own `selectedSizeChipValue` local state — same pattern
206	 * `organisms/zimmProductCard/index.stories.tsx`'s own `LiveSizeSelectionCard` already uses —
207	 * since the page renders many of these and this can't be a single page-level state variable.
208	 *
209	 * **Also resolves the real orderable variant for Add to Bag (2026-09-08, Gap 3 fix).** This is
210	 * the one component that ever knows which size is currently selected — `handleAddToBag` below is
211	 * built in the parent's render loop, with no access to this component's own local state, so
212	 * variant resolution has to happen here, not there. `hit` and `onResolvedAddToBag` are this
213	 * component's own props (not part of `ZimmProductCardProps` at all — `ZimmProductCard` itself
214	 * still only ever receives a plain, no-argument `onAddToBag`, matching its existing, unchanged
215	 * contract for every variation).
216	 */
217	type ProductListCardProps = Extract<ZimmProductCardProps, { variation: 'plp' }> & {
218	  hit: ProductListSearchHit;
219	  onResolvedAddToBag: (productId: string, price: number | undefined) => void;
220	};
221	
222	const ProductListCard = ({ hit, onResolvedAddToBag, ...cardProps }: ProductListCardProps) => {
223	  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(
224	    () => cardProps.selectedSizeChipValue,
225	  );
226	  const handleSizeChipSelect = (value: string) => {
227	    setSelectedSizeChipValue(value);
228	    cardProps.onSizeChipSelect?.(value);
229	  };
230	  const handleAddToBag = () => {
231	    // No selection -> today's existing default-variant behaviour, unchanged (no size selected
232	    // means default size). A selection that somehow matches no real
233	    // variant falls back the same way, rather than blocking the add entirely on a data mismatch.
234	    const resolved = selectedSizeChipValue ? resolveOrderableVariant(hit, selectedSizeChipValue) : null;
235	    const orderableProductId = resolved?.productId ?? hit.representedProduct?.id ?? hit.productId;
236	    onResolvedAddToBag(orderableProductId, resolved?.price ?? hit.price);
237	  };
238	
239	  return (
240	    <ZimmProductCard
241	      {...cardProps}
242	      selectedSizeChipValue={selectedSizeChipValue}
243	      onSizeChipSelect={handleSizeChipSelect}
244	      onAddToBag={handleAddToBag}
245	    />
246	  );
247	};
248	
249	type PageChipDatum = { key: string; label: string; onRemove: () => void };
250	
251	type SelectedChipRowProps = {
252	  chips: PageChipDatum[];
253	  visibleChips: PageChipDatum[];
254	  offset: number;
255	  canPageLeft: boolean;
256	  canPageRight: boolean;
257	  onOffsetChange: (next: number) => void;
258	  onClearAll: () => void;
259	};
260	
261	/**
262	 * SFCC-847 — CLEAR ALL + windowed applied-filter chips + paging arrows. Rendered as a
263	 * fragment so the caller owns the surrounding row: the desktop bar places it inline ahead of
264	 * FILTERS/Sort, while mobile gives it its own second row beneath the FILTERS/SORT BY row.
265	 * How many chips fit in the window is the caller's decision (see `chipsPerPage`).
266	 */
267	const SelectedChipRow = ({
268	  chips,
269	  visibleChips,
270	  offset,
271	  canPageLeft,
272	  canPageRight,
273	  onOffsetChange,
274	  onClearAll,
275	}: SelectedChipRowProps) => {
276	  if (chips.length === 0) return null;
277	
278	  return (
279	    <>
280	      <Box flexShrink={0} whiteSpace="nowrap">
281	        <ZimmLink label="Clear all" size="large" onClick={onClearAll} />
282	      </Box>
283	
284	      <Flex gap="var(--zimm-scale-xs)">
285	        {visibleChips.map((chip) => (
286	          <ZimmSelectedChip
287	            key={chip.key}
288	            label={chip.label}
289	            variant="secondary"
290	            onRemove={() => {
291	              chip.onRemove();
292	              if (offset > 0 && offset >= chips.length - 1) {
293	                onOffsetChange(offset - 1);
294	              }
295	            }}
296	          />
297	        ))}
298	      </Flex>
299	
300	      <ZimmButton
301	        variant="icon"
302	        icon="chevron-left"
303	        label="Previous chips"
304	        disabled={!canPageLeft}
305	        onClick={() => onOffsetChange(offset - 1)}
306	      />
307	      <ZimmButton
308	        variant="icon"
309	        icon="chevron-right"
310	        label="Next chips"
311	        disabled={!canPageRight}
312	        onClick={() => onOffsetChange(offset + 1)}
313	      />
314	    </>
315	  );
316	};
317	
318	/*
319	 * This is a simple product listing page. It displays a paginated list
320	 * of product hit objects. Allowing for sorting and filtering based on the
321	 * allowable filters and sort refinements.
322	 */
323	const ProductList = (props: ProductListProps) => {
324	  // Using destructuring to omit properties; we must rename `isLoading` because we use a different
325	  // `isLoading` later in this function.
326	  const { isLoading: _unusedIsLoading, staticContext: _unusedStaticContext, ...rest } = props;
327	  const filterDrawer = useDisclosure();
328	  // `intl.formatMessage`/`intl.formatNumber`, never a destructured `{ formatMessage }`: the
329	  // base file's own original destructure tripped `@typescript-eslint/unbound-method` (the
330	  // established fix already used elsewhere in this codebase — see
331	  // zimmProductStyleCode/index.tsx) — consolidated to the one `intl` object throughout.
332	  const intl = useIntl();
333	  const navigate = useNavigation();
334	  const buildUrl = useSafeHref();
335	  const history = useHistory();
336	  const { categoryId } = props;
337	  const location = useLocation();
338	  // Derive the parent categoryId from the URL path before any data loads — used to gate the
339	  // parent useCategory fetch below so we always have the sibling list on leaf pages.
340	  const cleanSegments = removeSiteLocaleFromPath(location.pathname).split('/').filter(Boolean);
341	  const parentCategoryIdFromPath = cleanSegments.length > 1 ? cleanSegments.slice(0, -1).join('-') : undefined;
342	  const toast = useToast();
343	  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
344	  // Passed into the card mapper rather than formatted there — keeps that mapper a pure function
345	  // with no react-intl dependency of its own, same split its own docblock documents.
346	  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });
347	  const einstein = useEinstein();
348	  const dataCloud = useDataCloud();
349	  const activeData = useActiveData();
350	  const { res } = useServerContext();
351	  const customerId = useCustomerId();
352	  const [searchParams, { stringify: stringifySearchParams }] = useSearchParams();
353	
354	  /**************** Page State ****************/
355	  // Offset into the applied-filter chip window, shared by the desktop bar and the mobile row.
356	  // Window size is breakpoint-dependent — see `chipsPerPage`.
357	  const [chipOffset, setChipOffset] = useState(0);
358	  const [sortOpen, setSortOpen] = useState(false);
359	  const [wishlistLoading, setWishlistLoading] = useState<string[]>([]);
360	  const [searchByInventory, setSearchByInventory] = useState<string | number | null>(null);
361	
362	  const urlParams = new URLSearchParams(location.search);
363	  const searchQuery = urlParams.get('q');
364	  const isSearch = !!searchQuery;
365	
366	  if (categoryId) {
367	    searchParams._refine.push(`cgid=${categoryId}`);
368	  }
369	
370	  /**************** Mutation Actions ****************/
371	  const { mutateAsync: createCustomerProductListItem } = useShopperCustomersMutation('createCustomerProductListItem');
372	  const { mutateAsync: deleteCustomerProductListItem } = useShopperCustomersMutation('deleteCustomerProductListItem');
373	
374	  /**************** Query Actions ****************/
375	  // _refine is an invalid param for useProductSearch, we don't want to pass it to API call
376	  const { _refine, ...restOfParams } = searchParams;
377	
378	  const refine = searchByInventory ? [..._refine, `ilids=${searchByInventory}`] : _refine;
379	
380	  const {
381	    isLoading,
382	    isFetched,
383	    isRefetching,
384	    data: productSearchResult,
385	  } = useProductSearch(
386	    {
387	      parameters: {
388	        ...restOfParams,
389	        perPricebook: true,
390	        allVariationProperties: true,
391	        allImages: true,
392	        expand: [
393	          'promotions',
394	          'variations',
395	          'prices',
396	          'images',
397	          'page_meta_tags',
398	          'custom_properties',
399	          'availability',
400	          'represented_products',
401	        ],
402	        refine,
403	      },
